const setUserReportsToIfChanged = `-- name: SetUserReportsToIfChanged :execrows
UPDATE users SET reports_to = $1::varchar, updated_at = CURRENT_TIMESTAMP
WHERE id = $2 AND reports_to IS DISTINCT FROM $1::varchar
`

type SetUserReportsToIfChangedParams struct {
	ReportsTo sql.NullString
	ID        string
}

// Only a real manager change writes (and bumps updated_at). A NULL reports_to
// clears the manager.
func (q *Queries) SetUserReportsToIfChanged(ctx context.Context, arg SetUserReportsToIfChangedParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setUserReportsToIfChanged, arg.ReportsTo, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertSnapshotTeam = `-- name: UpsertSnapshotTeam :one
INSERT INTO teams (id, name, team_lead_id, health_check_enabled, updated_at)
VALUES ($1, btrim($2::text), $3::varchar, COALESCE($4::boolean, true), CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET
	name = EXCLUDED.name,
	team_lead_id = COALESCE($3::varchar, teams.team_lead_id),
	health_check_enabled = COALESCE($4::boolean, teams.health_check_enabled),
	updated_at = CURRENT_TIMESTAMP
WHERE btrim(teams.name) IS DISTINCT FROM EXCLUDED.name
   OR teams.team_lead_id IS DISTINCT FROM COALESCE($3::varchar, teams.team_lead_id)
   OR teams.health_check_enabled IS DISTINCT FROM COALESCE($4::boolean, teams.health_check_enabled)
RETURNING (xmax = 0)::boolean AS inserted
`

type UpsertSnapshotTeamParams struct {
	ID                 string
	Name               string
	TeamLeadID         sql.NullString
	HealthCheckEnabled sql.NullBool
}

// team_lead_id and health_check_enabled use the bound parameters rather than
// EXCLUDED so a NULL (field omitted by the provider) preserves the existing
// value. An existing team is only written when a business field differs.
// is_active is decided afterwards by ReactivateTeams / DeactivateTeamsByIDs.
func (q *Queries) UpsertSnapshotTeam(ctx context.Context, arg UpsertSnapshotTeamParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, upsertSnapshotTeam,
		arg.ID,
		arg.Name,
		arg.TeamLeadID,
		arg.HealthCheckEnabled,
	)
	var inserted bool
	err := row.Scan(&inserted)
	return inserted, err
}

const upsertSnapshotUser = `-- name: UpsertSnapshotUser :one
INSERT INTO users (id, username, email, full_name, hierarchy_level_id, reports_to, password_hash, auth_type, updated_at)
VALUES ($1, btrim($2::text), btrim($3::text), btrim($4::text), $5, NULL, '', 'sso', CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET
	username = EXCLUDED.username,
	email = EXCLUDED.email,
	full_name = EXCLUDED.full_name,
	hierarchy_level_id = CASE
		WHEN users.hierarchy_level_id = $6::text AND EXCLUDED.hierarchy_level_id = $7::text THEN users.hierarchy_level_id
		ELSE EXCLUDED.hierarchy_level_id
	END,
	updated_at = CURRENT_TIMESTAMP
WHERE btrim(users.username) IS DISTINCT FROM EXCLUDED.username
   OR lower(btrim(users.email)) IS DISTINCT FROM lower(EXCLUDED.email)
   OR btrim(users.full_name) IS DISTINCT FROM EXCLUDED.full_name
   OR (users.hierarchy_level_id IS DISTINCT FROM EXCLUDED.hierarchy_level_id
       AND NOT (users.hierarchy_level_id = $6::text AND EXCLUDED.hierarchy_level_id = $7::text))
RETURNING (xmax = 0)::boolean AS inserted
`

type UpsertSnapshotUserParams struct {
	ID             string
	Username       string
	Email          string
	FullName       string
	Level          string
	PodLeadLevel   string
	PodSourceLevel string
}

// Writes an existing row only when a normalized business field differs, so
// re-syncing identical data touches nothing. RETURNING yields a row only when
// the statement inserted or updated; xmax = 0 tells an insert from an update.
// is_active, password_hash and auth_type are never overwritten on conflict.
// pod_lead_level / pod_source_level are empty strings when the pod-lead mapping
// is off, which match no real level.
func (q *Queries) UpsertSnapshotUser(ctx context.Context, arg UpsertSnapshotUserParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, upsertSnapshotUser,
		arg.ID,
		arg.Username,
		arg.Email,
		arg.FullName,
		arg.Level,
		arg.PodLeadLevel,
		arg.PodSourceLevel,
	)
	var inserted bool
	err := row.Scan(&inserted)
	return inserted, err
}
